package wb;
import android.content.*;import android.os.*;import java.lang.reflect.*;
/** Binds CarInfoService for get and door event subscription only. No set/write or root path. */
public final class VehicleReader {
 private final Context ctx;private volatile Object bus;private Class<?> event;private Method get;private boolean bound;private Object notify;public volatile String subscription="尚未订阅";public java.util.function.BiConsumer<Integer,Integer> doorListener;public volatile String status="等待连接";
 VehicleReader(Context c){ctx=c;}
 final ServiceConnection conn=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){try{event=Class.forName("com.desaysv.ivi.vdb.event.VDEvent");bus=Class.forName("com.desaysv.ivi.vdb.IVDBus$Stub").getMethod("asInterface",IBinder.class).invoke(null,b);get=Class.forName("com.desaysv.ivi.vdb.IVDBus").getMethod("get",event);status="已连接";subscribe();}catch(Exception e){status="接口不可用";}}public void onServiceDisconnected(ComponentName n){bus=null;status="连接断开";}};
 void subscribe(){try{
 Class<?> iface=Class.forName("com.desaysv.ivi.vdb.IVDBusNotify");
 Binder callback=new Binder(){protected boolean onTransact(int code,Parcel data,Parcel reply,int flags)throws RemoteException{if(code==IBinder.INTERFACE_TRANSACTION){if(reply!=null)reply.writeString("com.desaysv.ivi.vdb.IVDBusNotify");return true;}if(code!=1)return super.onTransact(code,data,reply,flags);data.enforceInterface("com.desaysv.ivi.vdb.IVDBusNotify");if(data.readInt()!=0)try{Parcelable.Creator<?> creator=(Parcelable.Creator<?>)event.getField("CREATOR").get(null);Object ev=creator.createFromParcel(data);int module=(Integer)event.getMethod("getId").invoke(ev);Bundle payload=(Bundle)event.getMethod("getPayload").invoke(ev);if(module==0x50004&&payload!=null&&!payload.getBoolean("IS_NULL",false)){int id=payload.getInt("CMD_ID",-1);int[] values=payload.getIntArray("VALUE");if(id>=15&&id<=18&&values!=null&&values.length==1&&(values[0]==0||values[0]==1)&&doorListener!=null){subscription="已收到门订阅回调";doorListener.accept(id-15,values[0]);}}}catch(Exception ignored){}if(reply!=null)reply.writeNoException();return true;}};
 notify=Proxy.newProxyInstance(iface.getClassLoader(),new Class<?>[]{iface},(proxy,method,args)->{if(method.getName().equals("asBinder"))return callback;if(method.getName().equals("hashCode"))return System.identityHashCode(proxy);if(method.getName().equals("equals"))return args!=null&&args.length==1&&proxy==args[0];if(method.getName().equals("toString"))return "DoorReadOnlyNotify";return null;});
 Bundle bundle=new Bundle();bundle.putIntArray("CMD_ID_ARRAY",new int[]{15,16,17,18});Object ev=event.getConstructor(int.class,Bundle.class).newInstance(0x50004,bundle);Class.forName("com.desaysv.ivi.vdb.IVDBus").getMethod("subscribeCustomizedEvent",event,iface).invoke(bus,ev,notify);subscription="订阅已提交（等待回调）";
 }catch(Exception ex){subscription="订阅失败，使用轮询";notify=null;}}
 void connect(){try{bound=ctx.bindService(new Intent("action.desaysv.ivi.vds.carinfo.SERVICE").setComponent(new ComponentName("com.desaysv.ivi.vds.carinfo","com.desaysv.ivi.vds.carinfo.service.CarInfoService")),conn,Context.BIND_AUTO_CREATE);if(!bound)status="服务未开放";}catch(Exception e){status="连接失败";}}
 synchronized int[] read(int module,int id){if(bus==null)return null;try{Bundle b=new Bundle();b.putInt("CMD_ID",id);Object rsp=get.invoke(bus,event.getConstructor(int.class,Bundle.class).newInstance(module,b));if(rsp==null)return null;Bundle p=(Bundle)event.getMethod("getPayload").invoke(rsp);if(p==null||p.getBoolean("IS_NULL",false))return null;int[] a=p.getIntArray("VALUE");return a!=null&&a.length>0?a:null;}catch(Exception e){return null;}}
 boolean connected(){return bus!=null;}
 void retry(){if(bus!=null)return;close();connect();}
 void close(){if(bus!=null&&notify!=null)try{Object ev=event.getConstructor(int.class,Bundle.class).newInstance(0x50004,new Bundle());Class.forName("com.desaysv.ivi.vdb.IVDBus").getMethod("unsubscribeCustomizedEvent",event,Class.forName("com.desaysv.ivi.vdb.IVDBusNotify")).invoke(bus,ev,notify);}catch(Exception ignored){}notify=null;subscription="未连接";if(bound)try{ctx.unbindService(conn);}catch(Exception ignored){}bound=false;bus=null;}
}
